-- GradManager MySQL Dump
-- Generated: 2026-07-25 22:41:54
-- Source: Nexacro Course Timetable XML (23-1 ~ 26-2)

SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE="NO_AUTO_VALUE_ON_ZERO";

DROP TABLE IF EXISTS `programs`;
CREATE TABLE `programs` (
  `program_id` INT NOT NULL AUTO_INCREMENT,
  `program_name` VARCHAR(100) NOT NULL,
  `program_type` VARCHAR(30) NOT NULL DEFAULT 'MAJOR',
  `required_credits` DECIMAL(5,1) DEFAULT NULL,
  `effective_from_year` INT NOT NULL,
  `effective_to_year` INT DEFAULT NULL,
  `source_url` TEXT NOT NULL,
  PRIMARY KEY (`program_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `courses`;
CREATE TABLE `courses` (
  `course_id` INT NOT NULL AUTO_INCREMENT,
  `course_code` VARCHAR(30) NOT NULL,
  `course_name` VARCHAR(150) NOT NULL,
  `credit` DECIMAL(3,1) NOT NULL,
  `theory_hours` DECIMAL(3,1) DEFAULT NULL,
  `practice_hours` DECIMAL(3,1) DEFAULT NULL,
  `course_description` TEXT DEFAULT NULL,
  `source_url` TEXT NOT NULL,
  PRIMARY KEY (`course_id`),
  UNIQUE KEY `uk_course_code` (`course_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `course_offerings`;
CREATE TABLE `course_offerings` (
  `offering_id` INT NOT NULL AUTO_INCREMENT,
  `course_id` INT NOT NULL,
  `academic_year` INT NOT NULL,
  `semester` VARCHAR(10) NOT NULL,
  `section` VARCHAR(20) NOT NULL,
  `professor_name` VARCHAR(100) DEFAULT NULL,
  `syllabus_url` TEXT DEFAULT NULL,
  PRIMARY KEY (`offering_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `course_schedules`;
CREATE TABLE `course_schedules` (
  `schedule_id` INT NOT NULL AUTO_INCREMENT,
  `offering_id` INT NOT NULL,
  `day_of_week` VARCHAR(10) NOT NULL,
  `start_time` TIME NOT NULL,
  `end_time` TIME NOT NULL,
  `classroom` VARCHAR(100) DEFAULT NULL,
  PRIMARY KEY (`schedule_id`),
  KEY `fk_schedule_offering` (`offering_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- ── User / Student tables ──

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `user_id` INT NOT NULL AUTO_INCREMENT,
  `login_id` VARCHAR(50) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `role` VARCHAR(20) NOT NULL DEFAULT 'STUDENT',
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uk_login_id` (`login_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `students`;
CREATE TABLE `students` (
  `student_id` INT NOT NULL AUTO_INCREMENT,
  `user_id` INT NOT NULL,
  `student_number` VARCHAR(20) NOT NULL,
  `admission_year` INT NOT NULL,
  `current_grade` INT NOT NULL,
  PRIMARY KEY (`student_id`),
  UNIQUE KEY `uk_student_user` (`user_id`),
  UNIQUE KEY `uk_student_number` (`student_number`),
  CONSTRAINT `fk_student_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `student_programs`;
CREATE TABLE `student_programs` (
  `student_program_id` INT NOT NULL AUTO_INCREMENT,
  `student_id` INT NOT NULL,
  `program_id` INT NOT NULL,
  `program_role` VARCHAR(20) NOT NULL DEFAULT 'PRIMARY',
  `selected_year` INT DEFAULT NULL,
  `completion_status` VARCHAR(20) DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`student_program_id`),
  CONSTRAINT `fk_sp_student` FOREIGN KEY (`student_id`) REFERENCES `students`(`student_id`),
  CONSTRAINT `fk_sp_program` FOREIGN KEY (`program_id`) REFERENCES `programs`(`program_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `student_course_history`;
CREATE TABLE `student_course_history` (
  `history_id` INT NOT NULL AUTO_INCREMENT,
  `student_id` INT NOT NULL,
  `course_id` INT NOT NULL,
  `academic_year` INT DEFAULT NULL,
  `semester` VARCHAR(10) DEFAULT NULL,
  `earned_credit` DECIMAL(3,1) DEFAULT NULL,
  `completion_status` VARCHAR(20) NOT NULL,
  `is_retake` BOOLEAN NOT NULL DEFAULT FALSE,
  `attempt_no` INT NOT NULL DEFAULT 1,
  `original_history_id` INT DEFAULT NULL,
  `credit_counted` BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (`history_id`),
  CONSTRAINT `fk_sch_student` FOREIGN KEY (`student_id`) REFERENCES `students`(`student_id`),
  CONSTRAINT `fk_sch_course` FOREIGN KEY (`course_id`) REFERENCES `courses`(`course_id`),
  CONSTRAINT `fk_sch_original` FOREIGN KEY (`original_history_id`) REFERENCES `student_course_history`(`history_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `user_interests`;
CREATE TABLE `user_interests` (
  `user_interest_id` INT NOT NULL AUTO_INCREMENT,
  `user_id` INT NOT NULL,
  `interest_type` VARCHAR(30) NOT NULL,
  `keyword` VARCHAR(100) NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_interest_id`),
  CONSTRAINT `fk_ui_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ── Curriculum tables ──

DROP TABLE IF EXISTS `curriculum_courses`;
CREATE TABLE `curriculum_courses` (
  `curriculum_course_id` INT NOT NULL AUTO_INCREMENT,
  `curriculum_year` INT NOT NULL,
  `course_id` INT NOT NULL,
  `recommended_grade` INT DEFAULT NULL,
  `semester` VARCHAR(10) DEFAULT NULL,
  `completion_type` VARCHAR(30) NOT NULL,
  `is_required` BOOLEAN NOT NULL DEFAULT FALSE,
  `note` TEXT DEFAULT NULL,
  PRIMARY KEY (`curriculum_course_id`),
  CONSTRAINT `fk_cc_course` FOREIGN KEY (`course_id`) REFERENCES `courses`(`course_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `graduation_requirements`;
CREATE TABLE `graduation_requirements` (
  `requirement_id` INT NOT NULL AUTO_INCREMENT,
  `admission_year` INT NOT NULL,
  `program_id` INT DEFAULT NULL,
  `requirement_category` VARCHAR(50) NOT NULL,
  `required_credits` DECIMAL(6,1) DEFAULT NULL,
  `requirement_text` TEXT DEFAULT NULL,
  `source_url` TEXT DEFAULT NULL,
  PRIMARY KEY (`requirement_id`),
  CONSTRAINT `fk_gr_program` FOREIGN KEY (`program_id`) REFERENCES `programs`(`program_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `program_courses`;
CREATE TABLE `program_courses` (
  `program_course_id` INT NOT NULL AUTO_INCREMENT,
  `program_id` INT NOT NULL,
  `course_id` INT NOT NULL,
  `effective_year` INT NOT NULL,
  `recognition_credit` DECIMAL(3,1) DEFAULT NULL,
  `is_required` BOOLEAN DEFAULT NULL,
  `note` TEXT DEFAULT NULL,
  PRIMARY KEY (`program_course_id`),
  CONSTRAINT `fk_pc_program` FOREIGN KEY (`program_id`) REFERENCES `programs`(`program_id`),
  CONSTRAINT `fk_pc_course` FOREIGN KEY (`course_id`) REFERENCES `courses`(`course_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ── AI / Keyword tables ──

DROP TABLE IF EXISTS `course_keywords`;
CREATE TABLE `course_keywords` (
  `keyword_id` INT NOT NULL AUTO_INCREMENT,
  `offering_id` INT NOT NULL,
  `keyword` VARCHAR(100) NOT NULL,
  `keyword_source` VARCHAR(20) NOT NULL,
  `confidence_score` DECIMAL(5,2) DEFAULT NULL,
  `keyword_category` VARCHAR(50) DEFAULT NULL,
  `weight` DECIMAL(5,2) DEFAULT NULL,
  `source_text` TEXT DEFAULT NULL,
  PRIMARY KEY (`keyword_id`),
  CONSTRAINT `fk_ck_offering` FOREIGN KEY (`offering_id`) REFERENCES `course_offerings`(`offering_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `course_recommendations`;
CREATE TABLE `course_recommendations` (
  `recommendation_id` INT NOT NULL AUTO_INCREMENT,
  `student_id` INT NOT NULL,
  `offering_id` INT NOT NULL,
  `match_score` DECIMAL(5,2) NOT NULL,
  `reason` TEXT DEFAULT NULL,
  `generated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`recommendation_id`),
  CONSTRAINT `fk_cr_student` FOREIGN KEY (`student_id`) REFERENCES `students`(`student_id`),
  CONSTRAINT `fk_cr_offering` FOREIGN KEY (`offering_id`) REFERENCES `course_offerings`(`offering_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ── Chat tables ──

DROP TABLE IF EXISTS `chat_sessions`;
CREATE TABLE `chat_sessions` (
  `session_id` INT NOT NULL AUTO_INCREMENT,
  `user_id` INT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`session_id`),
  CONSTRAINT `fk_cs_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `chat_messages`;
CREATE TABLE `chat_messages` (
  `message_id` INT NOT NULL AUTO_INCREMENT,
  `session_id` INT NOT NULL,
  `sender_type` VARCHAR(20) NOT NULL,
  `message_text` TEXT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`message_id`),
  CONSTRAINT `fk_cm_session` FOREIGN KEY (`session_id`) REFERENCES `chat_sessions`(`session_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ── Academic events / Notices ──

DROP TABLE IF EXISTS `academic_events`;
CREATE TABLE `academic_events` (
  `event_id` INT NOT NULL AUTO_INCREMENT,
  `academic_year` INT NOT NULL,
  `semester` VARCHAR(10) DEFAULT NULL,
  `event_name` VARCHAR(200) NOT NULL,
  `event_type` VARCHAR(50) NOT NULL,
  `start_date` DATE NOT NULL,
  `end_date` DATE DEFAULT NULL,
  `is_mandatory` BOOLEAN NOT NULL DEFAULT TRUE,
  `description` TEXT DEFAULT NULL,
  `source_url` TEXT DEFAULT NULL,
  PRIMARY KEY (`event_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `notices`;
CREATE TABLE `notices` (
  `notice_id` INT NOT NULL AUTO_INCREMENT,
  `source_board` VARCHAR(100) NOT NULL,
  `title` VARCHAR(300) NOT NULL,
  `category` VARCHAR(50) DEFAULT NULL,
  `posted_date` DATE NOT NULL,
  `notice_url` TEXT NOT NULL,
  `content` TEXT DEFAULT NULL,
  PRIMARY KEY (`notice_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS=1;